import{n as e,r as t}from"./rolldown-runtime-BgaNhQyE.js";var n=t({FORMULA_CASES:()=>i}),r,i,a=e((()=>{r=`2026-08-09`,i=[{id:`rl-state-value`,slug:`reinforcement-learning-state-value`,title:`State value under a policy`,domain:`reinforcement-learning`,level:`common`,tex:`V_\\pi(s)=\\mathbb{E}_\\pi[G_t\\mid S_t=s]`,accessibleText:`V sub pi of s equals the expected return G at time t, under policy pi, given that the state at time t is s.`,purpose:`Defines how valuable a state is when future actions are selected by policy pi.`,provenance:`paper-displayed`,provenanceNote:`This is the standard state-value definition in Sutton and Barto, with typography normalized for Fanout.`,symbols:[{notationId:`subscript`,symbol:`V_\\pi, G_t, S_t`,role:`The subscripts label the governing policy and the time index; they are not multiplication.`},{notationId:`equals`,symbol:`=`,role:`Connects the value-function expression to its defining expectation.`},{notationId:`expectation`,symbol:`\\mathbb{E}_\\pi`,role:`Averages over trajectories generated while following policy pi.`},{notationId:`vertical-bar`,senseId:`conditioning`,symbol:`\\mid`,role:`Restricts the average to trajectories whose current state equals s.`}],decoder:{define:[`V_pi(s) is the state-value function evaluated at state s under policy pi.`,`G_t is the random return accumulated from time t onward.`,`S_t is the random state at time t, while lowercase s is one state value.`],establish:[`V_pi(s) and G_t are scalars; the expectation averages possible scalar returns over policy-induced trajectories.`],chunk:[`Outer statement: V_pi(s) equals an expected value.`,`Averaged quantity: the future return G_t.`,`Condition: only futures beginning with S_t=s are included.`],mainOperator:`The expectation is the main verb: average future returns over uncertainty while holding the current state fixed.`,describe:`The value of state s is the average return you should expect after arriving there and continuing with policy pi.`,execute:{setup:`Suppose three equally likely futures from state s have returns 2, 5, and 8.`,steps:[`Add the returns: 2+5+8=15.`,`Divide by three equally likely futures: 15/3=5.`],result:`The tiny-example estimate is V_pi(s)=5.`},relate:`This is a definition, not an update rule. A paper may later introduce Bellman equations or estimators for calculating it.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`sutton-barto-rl`]}},{id:`scaled-dot-product-attention`,slug:`scaled-dot-product-attention`,title:`Scaled dot-product attention`,domain:`transformers`,level:`common`,tex:`\\operatorname{Attention}(Q,K,V)=\\operatorname{softmax}\\left(\\frac{QK^\\top}{\\sqrt{d_k}}\\right)V`,accessibleText:`Attention of Q, K, and V equals softmax of Q times K transpose divided by the square root of d sub k, then multiplied by V.`,purpose:`Turns query-key similarity scores into normalized weights and uses them to combine value vectors.`,provenance:`paper-displayed`,provenanceNote:`The equation is the scaled dot-product attention definition in section 3.2.1 of the Transformer paper.`,symbols:[{notationId:`equals`,symbol:`=`,role:`Defines the output of the Attention function.`},{notationId:`matrix-product`,symbol:`QK^\\top and (... )V`,role:`The first product forms pairwise scores; the second forms weighted value combinations.`,shape:`For one head: (L_q×d_k)(d_k×L_k)→L_q×L_k, then (L_q×L_k)(L_k×d_v)→L_q×d_v.`},{notationId:`transpose`,symbol:`K^\\top`,role:`Swaps key axes so the shared key dimension can contract with each query.`},{notationId:`subscript`,symbol:`d_k`,role:`Names the dimensionality of each key vector.`},{notationId:`softmax`,symbol:`\\operatorname{softmax}`,role:`Normalizes each score row into positive weights summing to one.`},{notationId:`fraction`,symbol:`\\frac{QK^\\top}{\\sqrt{d_k}}`,role:`Divides every query-key score by the shared scale in the denominator.`},{notationId:`square-root`,symbol:`\\sqrt{d_k}`,role:`Produces the dimension-dependent score scale used before softmax.`}],decoder:{define:[`Q contains query vectors, K contains key vectors, and V contains value vectors.`,`d_k is the key dimension used by each dot product.`,`Softmax is applied across the key positions for each query.`],establish:[`For a single head, Q is L_q by d_k, K is L_k by d_k, and V is L_k by d_v.`],chunk:[`Score: multiply Q by K transpose to compare every query with every key.`,`Scale: divide all scores by square root d_k.`,`Normalize: apply softmax across keys.`,`Mix: multiply the weights by V.`],mainOperator:`The outer data flow is a normalized weighted sum: score, scale, normalize, then mix values.`,describe:`Each query decides how much attention to place on every key, then blends the associated values using those weights.`,execute:{setup:`For one query with scaled scores [0, ln 3], softmax produces weights [1/4, 3/4]. Let scalar values be [4, 8].`,steps:[`Normalize the scores into weights 0.25 and 0.75.`,`Compute 0.25×4 + 0.75×8.`],result:`The attended value is 7.`},relate:`This is the Transformer paper's core attention primitive; masking and batching add structure around it without changing this central operation.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`attention-paper`]}},{id:`gradient-descent-update`,slug:`gradient-descent-parameter-update`,title:`Gradient-descent parameter update`,domain:`optimization`,level:`foundational`,tex:`\\theta_{t+1}=\\theta_t-\\eta\\nabla_\\theta\\mathcal{L}(\\theta_t)`,accessibleText:`Theta at time t plus one equals theta at time t minus eta times the gradient with respect to theta of the loss at theta t.`,purpose:`Updates parameters by taking a learning-rate-sized step opposite the local loss gradient.`,provenance:`paper-displayed`,provenanceNote:`This is the conventional gradient-descent update presented in optimization treatments; symbols are normalized to common ML usage.`,symbols:[{notationId:`theta`,symbol:`\\theta`,role:`The parameter vector being optimized.`,shape:`The gradient has the same shape as theta.`},{notationId:`subscript`,symbol:`t, t+1`,role:`Labels the current and next optimization iterations.`},{notationId:`equals`,symbol:`=`,role:`Defines the next iterate from the current one.`},{notationId:`gradient`,symbol:`\\nabla_\\theta`,role:`Computes how the scalar loss changes along every parameter coordinate.`,shape:`Same shape as theta.`},{notationId:`eta`,symbol:`\\eta`,role:`The positive scalar learning rate that controls update size.`}],decoder:{define:[`Theta_t is the current parameter vector and theta_(t+1) is the next one.`,`Eta is a positive learning rate controlling step size.`,`L is a scalar loss and nabla_theta L is its parameter gradient.`],establish:[`Theta and its gradient have identical shapes, so subtraction is valid; eta is a scalar multiplier.`],chunk:[`Start from the current parameter vector theta_t.`,`Compute the local uphill direction nabla_theta L.`,`Scale it by eta and subtract to move downhill.`],mainOperator:`The equals sign defines an iterative update, while subtraction reverses the gradient's uphill direction.`,describe:`Measure which way makes loss rise fastest, then move a controlled distance the other way.`,execute:{setup:`Let theta_t=4, eta=0.1, and the loss gradient at theta_t be 6.`,steps:[`Scale the gradient: 0.1×6=0.6.`,`Subtract it from the current value: 4−0.6=3.4.`],result:`The next parameter value is theta_(t+1)=3.4.`},relate:`This is an update rule rather than the optimization objective itself; optimizers such as momentum and Adam modify the direction or scaling.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`deep-learning-optimization`]}},{id:`kv-cache-memory`,slug:`kv-cache-memory-bytes`,title:`Decoder KV-cache memory`,domain:`gpu-inference`,level:`common`,tex:`M_{KV}=2L_{layers}n_{kv}d_{head}T B b`,accessibleText:`K V cache memory equals two times layer count times K V head count times head dimension times cached tokens times active sequences times bytes per element.`,purpose:`Estimates the raw decoder self-attention key-and-value cache bytes for a homogeneous transformer configuration.`,provenance:`fanout-derived`,provenanceNote:`This byte count is derived from tensor shape and element size. It is not quoted as a displayed equation from GQA or PagedAttention; those sources ground the head structure and serving-memory motivation.`,symbols:[{notationId:`equals`,symbol:`=`,role:`Defines the idealized byte count under the listed assumptions.`},{notationId:`subscript`,symbol:`KV, layers, kv, head`,role:`Uses descriptive subscripts to name roles, not array positions.`},{notationId:`scalar-multiplication`,symbol:`2L_{layers}n_{kv}d_{head}TBb`,role:`Multiplies independent capacity dimensions; the leading two accounts for both keys and values.`}],decoder:{define:[`L_layers is decoder layer count, n_kv is key-value head count, and d_head is dimensions per head.`,`T is cached tokens per active sequence, B is active sequences, and b is bytes per stored element.`,`The leading factor two stores one key tensor and one value tensor.`],establish:[`Every factor except b is a count; multiplying by bytes per element gives bytes as the final unit.`],chunk:[`Per token and layer: two arrays times KV heads times head dimension.`,`Across time: multiply by cached token count T.`,`Across serving: multiply by active sequence count B.`,`Convert elements to bytes with b.`],mainOperator:`Multiplication is the main operation because each independent tensor axis expands the number of stored elements.`,describe:`Count every cached key and value element across layers, heads, tokens, and active sequences, then convert elements to bytes.`,execute:{setup:`Use 32 layers, 8 KV heads, head dimension 128, 4,096 cached tokens, one sequence, and two bytes per element.`,steps:[`Per token across layers: 2×32×8×128=65,536 elements.`,`Across 4,096 tokens: 65,536×4,096=268,435,456 elements.`,`At two bytes each: 536,870,912 bytes.`],result:`The idealized raw KV cache is 512 MiB for one sequence.`},relate:`This is a capacity estimate. Allocator blocks, fragmentation, metadata, cross-attention, prefixes, quantization, and runtime layout can change observed memory.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`gqa-paper`,`pagedattention-paper`]}},{id:`roofline-bound`,slug:`roofline-performance-bound`,title:`Roofline attainable-performance bound`,domain:`gpu-inference`,level:`common`,tex:`P_{attainable}=\\min(P_{peak}, BW\\cdot I)`,accessibleText:`Attainable performance equals the minimum of peak compute performance and memory bandwidth times arithmetic intensity.`,purpose:`Bounds attainable kernel performance by whichever ceiling is lower: compute throughput or data-movement throughput.`,provenance:`paper-displayed`,provenanceNote:`This is the Roofline paper's central attainable-performance relationship, using arithmetic intensity I and bandwidth BW notation.`,symbols:[{notationId:`subscript`,symbol:`attainable, peak`,role:`Descriptive subscripts distinguish achieved-bound performance from hardware peak.`},{notationId:`equals`,symbol:`=`,role:`States the model's attainable-performance ceiling.`},{notationId:`minimum`,symbol:`\\min`,role:`Selects the tighter of the compute and bandwidth ceilings.`},{notationId:`scalar-multiplication`,symbol:`\\cdot`,role:`Here the centered dot is ordinary scalar multiplication, not a vector dot product.`}],decoder:{define:[`P_peak is the hardware's peak floating-point throughput.`,`BW is peak memory bandwidth in bytes per second.`,`I is arithmetic intensity in floating-point operations per byte moved.`],establish:[`BW×I has units bytes/second × FLOPs/byte = FLOPs/second, matching P_peak.`],chunk:[`Compute ceiling: the hardware cannot exceed P_peak.`,`Bandwidth ceiling: data movement supports at most BW×I work per second.`,`The minimum chooses the active bottleneck.`],mainOperator:`Minimum is the main verb: performance is capped by the lower of two independently calculated roofs.`,describe:`A kernel runs no faster than its compute hardware or its ability to feed data, whichever limit is reached first.`,execute:{setup:`Let peak compute be 100 TFLOP/s, bandwidth be 2 TB/s, and intensity be 20 FLOPs/byte.`,steps:[`Compute the bandwidth roof: 2 TB/s × 20 FLOPs/byte = 40 TFLOP/s.`,`Compare 40 TFLOP/s with the 100 TFLOP/s compute peak.`],result:`The model bounds attainable performance at 40 TFLOP/s, so this case is bandwidth-limited.`},relate:`The Roofline model is an upper-bound diagnostic, not a latency prediction; overheads and imperfect utilization can place real performance below the roof.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`roofline-paper`]}},{id:`bayes-rule`,slug:`bayes-rule-posterior-update`,title:`Bayes' rule`,domain:`probability-statistics`,level:`foundational`,tex:`p(\\theta\\mid x)=\\frac{p(x\\mid\\theta)p(\\theta)}{p(x)}`,accessibleText:`The probability of theta given x equals the probability of x given theta times the prior probability of theta, divided by the probability of x.`,purpose:`Updates a prior belief about a parameter after observing evidence by reweighting parameter values according to how well they predict that evidence.`,provenance:`paper-displayed`,provenanceNote:`This is Bayes' theorem in the parameter-and-observation notation used throughout machine learning, as presented in Mathematics for Machine Learning.`,symbols:[{notationId:`equals`,symbol:`=`,role:`Relates the normalized posterior on the left to its likelihood-prior construction.`},{notationId:`vertical-bar`,senseId:`conditioning`,symbol:`\\mid`,role:`Reads as given; the expression to the right is held known in each conditional density.`},{notationId:`fraction`,symbol:`\\frac{\\cdot}{p(x)}`,role:`Divides by the evidence so the posterior distribution normalizes to one.`},{notationId:`likelihood`,symbol:`p(x\\mid\\theta)`,role:`Scores how compatible the observed x is with each candidate theta.`},{notationId:`scalar-multiplication`,symbol:`p(x\\mid\\theta)p(\\theta)`,role:`Combines likelihood and prior pointwise for each theta.`}],decoder:{define:[`Theta is the unknown parameter or hypothesis, while x is the observed evidence.`,`p(theta) is the prior, p(x given theta) is the likelihood, p(theta given x) is the posterior, and p(x) is the evidence.`],establish:[`For one discrete theta value, every displayed p term is scalar; across all theta values the posterior entries must sum to one.`],chunk:[`Numerator: multiply prior belief by compatibility with the observation.`,`Denominator: average that numerator across all possible parameter values to normalize it.`,`Left side: the resulting updated distribution after x is known.`],mainOperator:`Conditioning is the conceptual verb: Bayes' rule reverses which variable is treated as known by reweighting and normalizing.`,describe:`Start with what you believed before x, reward parameter values that predict x well, and renormalize the updated beliefs.`,execute:{setup:`Suppose two hypotheses have priors 0.5 each and likelihoods p(x|A)=0.8 and p(x|B)=0.2.`,steps:[`Compute unnormalized weights: A gets 0.8×0.5=0.4 and B gets 0.2×0.5=0.1.`,`Normalize by evidence 0.4+0.1=0.5.`],result:`The posterior probabilities are p(A|x)=0.8 and p(B|x)=0.2.`},relate:`This is an exact identity. In large models the denominator or posterior may be computationally intractable, motivating variational or sampling approximations.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`mml-book`]}},{id:`categorical-cross-entropy`,slug:`categorical-cross-entropy-from-softmax`,title:`Categorical cross-entropy from logits`,domain:`information-theory`,level:`foundational`,tex:`\\mathcal{L}_{CE}(z,y)=-\\sum_i y_i\\log\\!\\left(\\operatorname{softmax}(z)_i\\right)`,accessibleText:`Cross-entropy loss of logits z and target y equals the negative sum over classes i of target y i times the log of softmax z at class i.`,purpose:`Converts unnormalized class logits into probabilities and penalizes low probability assigned to the observed target class.`,provenance:`paper-displayed`,provenanceNote:`This combines the standard softmax definition with categorical cross-entropy in the conventional machine-learning loss form documented in Mathematics for Machine Learning.`,symbols:[{notationId:`cross-entropy`,symbol:`\\mathcal{L}_{CE}`,role:`Names the scalar discrepancy between the target distribution and predicted probabilities.`},{notationId:`softmax`,symbol:`\\operatorname{softmax}(z)_i`,role:`Converts the full logit vector into one normalized probability per class.`},{notationId:`summation`,symbol:`\\sum_i`,role:`Aggregates the target-weighted surprise across classes.`},{notationId:`logarithm`,symbol:`\\log`,role:`Turns a small assigned probability into a large negative score before the outer minus sign.`},{notationId:`subscript`,symbol:`i, CE`,role:`Uses i as a bound class index and CE as a descriptive loss label.`}],decoder:{define:[`z is a vector of real-valued class logits and y is a matching target probability vector.`,`Softmax z at i is the model probability for class i, and L CE is one scalar loss.`],establish:[`z and y have the same class dimension C; softmax preserves that shape and the summation reduces the class axis to a scalar.`],chunk:[`Normalize every logit with softmax.`,`Take the logarithm of each predicted probability.`,`Weight by the target entries, add across classes, and negate.`],mainOperator:`The summation is the outer reduction, while softmax and logarithm transform each class score before aggregation.`,describe:`Turn scores into probabilities, keep the log probability relevant to the target distribution, and make confident mistakes expensive.`,execute:{setup:`Let the target be class two, y=[0,1], and the softmax probabilities be [0.25,0.75].`,steps:[`The first target weight is zero, so its term vanishes.`,`The remaining term is −log(0.75).`],result:`The loss is approximately 0.288 nats.`},relate:`This is an objective definition. Implementations usually fuse softmax and log-sum-exp for numerical stability rather than computing probabilities first.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`mml-book`]}},{id:`kl-divergence`,slug:`kullback-leibler-divergence`,title:`Kullback-Leibler divergence`,domain:`information-theory`,level:`common`,tex:`D_{\\mathrm{KL}}(p\\Vert q)=\\sum_x p(x)\\log\\frac{p(x)}{q(x)}`,accessibleText:`K L divergence from p to q equals the sum over x of p of x times the logarithm of p of x divided by q of x.`,purpose:`Measures the expected log-density mismatch when outcomes follow p but are represented using q.`,provenance:`paper-displayed`,provenanceNote:`This is the standard discrete KL-divergence definition, with natural logarithms giving units of nats.`,symbols:[{notationId:`kl-divergence`,symbol:`D_{\\mathrm{KL}}(p\\Vert q)`,role:`Names an ordered divergence whose first distribution supplies the expectation weights.`},{notationId:`summation`,symbol:`\\sum_x`,role:`Adds one contribution for every possible discrete outcome x.`},{notationId:`logarithm`,symbol:`\\log`,role:`Measures the multiplicative probability ratio on an additive scale.`},{notationId:`fraction`,symbol:`\\frac{p(x)}{q(x)}`,role:`Compares how much probability the two distributions assign to the same outcome.`}],decoder:{define:[`p and q are probability distributions over the same support.`,`The double vertical bar separates the ordered arguments; it does not make the divergence symmetric.`],establish:[`Each p(x), q(x), log ratio, and weighted term is scalar; the sum returns one nonnegative scalar when the support conditions hold.`],chunk:[`At each outcome, form the probability ratio p(x)/q(x).`,`Take its logarithm and weight it by p(x).`,`Add the weighted mismatch over all outcomes.`],mainOperator:`The p-weighted summation is an expectation: average the log probability ratio under outcomes drawn from p.`,describe:`Ask how surprised you would be, on average under p, if you used q's probabilities instead.`,execute:{setup:`Let p=[0.5,0.5] and q=[0.25,0.75].`,steps:[`First term: 0.5 log(0.5/0.25)=0.5 log 2.`,`Second term: 0.5 log(0.5/0.75)=0.5 log(2/3).`,`Add the two terms.`],result:`D KL(p||q) is approximately 0.144 nats.`},relate:`KL is a divergence rather than a metric: reversing p and q generally changes the value, and support mismatch can make it infinite.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`mml-book`]}},{id:`adam-update`,slug:`adam-bias-corrected-update`,title:`Adam parameter update`,domain:`optimization`,level:`common`,tex:`\\theta_t=\\theta_{t-1}-\\alpha\\frac{\\hat m_t}{\\sqrt{\\hat v_t}+\\epsilon}`,accessibleText:`Theta at step t equals theta at the previous step minus alpha times bias-corrected first moment m hat t divided by the square root of corrected second moment v hat t plus epsilon.`,purpose:`Updates each parameter using a smoothed gradient divided by an adaptive scale derived from recent squared gradients.`,provenance:`paper-displayed`,provenanceNote:`This is the bias-corrected Adam update from Algorithm 1 of the original Adam paper.`,symbols:[{notationId:`theta`,symbol:`\\theta_t`,role:`The parameter tensor or parameter tree being updated.`},{notationId:`learning-rate-alpha`,symbol:`\\alpha`,role:`The positive base step size for the adaptive update.`},{notationId:`adam-bias-correction`,symbol:`\\hat m_t,\\hat v_t`,role:`Marks first and second moment estimates corrected for zero-initialization bias.`},{notationId:`square-root`,symbol:`\\sqrt{\\hat v_t}`,role:`Converts the second raw moment into a root-mean-square-like coordinate scale.`},{notationId:`epsilon`,symbol:`\\epsilon`,role:`Keeps the denominator away from zero for numerical stability.`},{notationId:`fraction`,symbol:`\\frac{\\hat m_t}{\\sqrt{\\hat v_t}+\\epsilon}`,role:`Rescales each first-moment coordinate by its adaptive denominator.`}],decoder:{define:[`m hat t is the bias-corrected exponential average of gradients.`,`v hat t is the bias-corrected exponential average of squared gradients.`,`Alpha is the base step size and epsilon is a small stabilizing scalar.`],establish:[`Theta, m hat, and v hat share the same parameter shape; square root, division, and addition act elementwise, while alpha and epsilon broadcast.`],chunk:[`Build the adaptive direction: m hat divided by square root v hat plus epsilon.`,`Scale that direction by alpha.`,`Subtract it from the previous parameters.`],mainOperator:`The equals sign defines an iterative update; the fraction is the adaptive coordinate-wise preconditioner.`,describe:`Move in the smoothed gradient direction, but take smaller coordinate steps where recent gradients have been large.`,execute:{setup:`For one parameter use theta previous=2, alpha=0.1, m hat=0.6, v hat=0.36, and epsilon small enough to ignore in this toy calculation.`,steps:[`Square root v hat is 0.6.`,`The adaptive direction is 0.6/0.6=1.`,`Subtract alpha times one from two.`],result:`The updated parameter is approximately 1.9.`},relate:`This line is only the final Adam update; the paper's algorithm also defines how m, v, and their bias corrections evolve.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`adam-paper`]}},{id:`bellman-optimality`,slug:`bellman-optimality-action-value`,title:`Bellman optimality equation`,domain:`reinforcement-learning`,level:`common`,tex:`Q_*(s,a)=\\mathbb{E}\\!\\left[R_{t+1}+\\gamma\\max_{a'}Q_*(S_{t+1},a')\\mid S_t=s,A_t=a\\right]`,accessibleText:`Optimal Q of state s action a equals the expected next reward plus gamma times the maximum over next actions a prime of optimal Q at the next state and action, given the current state and action.`,purpose:`Defines optimal action value recursively through one observed transition and the best possible continuation.`,provenance:`paper-displayed`,provenanceNote:`This is the standard Bellman optimality equation for action values in Sutton and Barto.`,symbols:[{notationId:`bellman-optimality`,symbol:`Q_*(s,a)=\\mathbb{E}[R+\\gamma\\max Q_*]`,role:`Names the optimal fixed-point relation decoded by the complete formula.`},{notationId:`expectation`,symbol:`\\mathbb{E}`,role:`Averages immediate rewards and next states under environment dynamics.`},{notationId:`maximum`,symbol:`\\max_{a'}`,role:`Selects the largest continuation value at the next state.`},{notationId:`discount-factor`,symbol:`\\gamma`,role:`Downweights value that begins one transition later.`},{notationId:`prime`,symbol:`a'`,role:`Distinguishes the candidate next action from the current action a.`},{notationId:`vertical-bar`,senseId:`conditioning`,symbol:`\\mid`,role:`Fixes the current state-action pair inside the expectation.`}],decoder:{define:[`Q star s a is the best achievable expected return after the current state-action pair.`,`R t plus one and S t plus one are the random reward and state produced by the environment transition.`,`a prime ranges over actions available in the next state.`],establish:[`Every Q value and reward is scalar; maximum reduces the next-action axis, and expectation reduces transition uncertainty.`],chunk:[`One-step outcome: receive R at the next time.`,`Optimal continuation: choose the largest Q star over next actions.`,`Discount continuation by gamma, add reward, then average possible transitions.`],mainOperator:`Expectation is outermost, with an inner maximum expressing optimal choice after the environment reveals the next state.`,describe:`The value of acting now equals the average immediate reward plus the discounted value of choosing perfectly afterward.`,execute:{setup:`Suppose the next reward is always 2, gamma=0.9, and the next state's action values are 3 and 5.`,steps:[`Choose the best next value: max(3,5)=5.`,`Discount it: 0.9×5=4.5.`,`Add the immediate reward: 2+4.5.`],result:`The action value for this deterministic toy transition is 6.5.`},relate:`This is a fixed-point definition. Value iteration and Q-learning turn it into computational update rules.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`sutton-barto-rl`]}},{id:`ppo-clipped-objective`,slug:`ppo-clipped-surrogate-objective`,title:`PPO clipped surrogate objective`,domain:`reinforcement-learning`,level:`advanced`,tex:`L^{CLIP}(\\theta)=\\mathbb{E}_t\\!\\left[\\min\\!\\left(r_t(\\theta)\\hat A_t,\\operatorname{clip}(r_t(\\theta),1-\\epsilon,1+\\epsilon)\\hat A_t\\right)\\right]`,accessibleText:`PPO clipped objective of theta equals the expectation over time of the minimum between policy ratio r t times advantage A hat t and the clipped policy ratio times the same advantage.`,purpose:`Limits the optimization incentive from policy probability ratios that move too far from the data-collecting policy.`,provenance:`paper-displayed`,provenanceNote:`This is Equation 7, the clipped surrogate objective, from the original PPO paper with typography normalized.`,symbols:[{notationId:`expectation`,symbol:`\\mathbb{E}_t`,role:`Averages per-sample surrogate values over collected time steps or minibatch items.`},{notationId:`minimum`,symbol:`\\min`,role:`Chooses the more pessimistic of the unclipped and clipped surrogate terms.`},{notationId:`importance-ratio`,symbol:`r_t(\\theta)`,role:`Compares current-policy probability with old-policy probability for the sampled action.`},{notationId:`ppo-clipping`,symbol:`\\operatorname{clip}(r_t,1-\\epsilon,1+\\epsilon)`,role:`Bounds the ratio used by one branch of the surrogate.`},{notationId:`advantage`,symbol:`\\hat A_t`,role:`Supplies the signed relative quality of the sampled action.`},{notationId:`epsilon`,symbol:`\\epsilon`,role:`Sets the half-width of the allowed ratio interval around one.`}],decoder:{define:[`r t theta is the new-policy probability divided by old-policy probability for the sampled action.`,`A hat t is an estimated advantage whose sign says whether increasing that action's probability is desirable.`,`Epsilon defines the clipping interval from one minus epsilon to one plus epsilon.`],establish:[`Ratio and advantage are scalars per sample; clipping and minimum preserve the sample axis before expectation reduces it.`],chunk:[`Unclipped branch: multiply the current policy ratio by advantage.`,`Clipped branch: bound the ratio, then multiply by the same advantage.`,`Take the smaller branch per sample and average.`],mainOperator:`Minimum is the conservative gate inside an outer expectation; its effect depends on the advantage sign.`,describe:`Reward useful policy changes, but stop giving extra objective improvement once the probability ratio moves beyond the trusted interval.`,execute:{setup:`Let epsilon=0.2, ratio r=1.4, and positive advantage A=2.`,steps:[`Unclipped term: 1.4×2=2.8.`,`Clipped ratio: clip(1.4,0.8,1.2)=1.2, so clipped term is 2.4.`,`Take min(2.8,2.4).`],result:`This sample contributes 2.4 to the maximized surrogate objective.`},relate:`This is a surrogate training objective, not a guarantee that the final policy ratio remains inside the interval for every sample.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`ppo-paper`]}},{id:`ring-all-reduce-volume`,slug:`ring-all-reduce-bytes-per-rank`,title:`Ring all-reduce communication volume`,domain:`gpu-inference`,level:`advanced`,tex:`V_{ring}=2\\frac{p-1}{p}N b`,accessibleText:`Ring communication volume per rank equals two times p minus one divided by p, times N elements, times b bytes per element.`,purpose:`Estimates ideal bytes sent by each rank when an N-element tensor is all-reduced using a bandwidth-optimal reduce-scatter followed by all-gather ring.`,provenance:`fanout-derived`,provenanceNote:`This byte count is derived from NCCL's reduce-scatter plus all-gather decomposition and the ideal ring schedule. NCCL may select other algorithms, protocols, chunking, or topology-specific paths.`,symbols:[{notationId:`all-reduce`,symbol:`V_{ring}`,role:`The target collective reduces values and returns the complete result to every rank.`},{notationId:`fraction`,symbol:`\\frac{p-1}{p}`,role:`Accounts for sending p minus one of p equal tensor chunks in each ring phase.`},{notationId:`scalar-multiplication`,symbol:`2\\frac{p-1}{p}Nb`,role:`Multiplies two phases by the per-phase tensor fraction and bytes represented.`},{notationId:`bytes-per-element`,symbol:`b`,role:`Converts N logical tensor elements into bytes.`},{notationId:`reduce-scatter`,symbol:`first factor of the leading 2`,role:`One ring phase reduces and distributes result shards.`},{notationId:`all-gather`,symbol:`second factor of the leading 2`,role:`The second ring phase reconstructs the complete result on every rank.`}],decoder:{define:[`p is the number of participating ranks, N is total tensor elements, and b is bytes stored per element.`,`V ring is ideal bytes sent per rank across the two collective phases.`,`The leading two counts reduce-scatter and all-gather.`],establish:[`p and N are counts, b is bytes per element, and the p ratio is dimensionless, so the result has units of bytes per rank.`],chunk:[`Shard factor: each rank sends p minus one of p tensor chunks in one ring phase.`,`Payload: N elements times b bytes per element.`,`Two phases: multiply by two for reduce-scatter plus all-gather.`],mainOperator:`Multiplication combines phase count, ring traversal fraction, tensor element count, and element width into a byte estimate.`,describe:`In each of two ring phases, every rank sends almost one full tensor, split into equal chunks across its peers.`,execute:{setup:`Use p=4 ranks, N=1,000,000 elements, and b=2 bytes per element.`,steps:[`The per-phase fraction is (4−1)/4=0.75.`,`One phase sends 0.75×1,000,000×2=1,500,000 bytes.`,`Two phases send 3,000,000 bytes per rank.`],result:`The ideal ring volume is 3 MB sent per rank, excluding protocol and topology overhead.`},relate:`This is a communication-volume estimate, not a duration model; link bandwidth, contention, latency, topology, and algorithm selection determine elapsed time.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`nccl-collectives`]}},{id:`autoregressive-likelihood`,slug:`autoregressive-sequence-log-likelihood`,title:`Autoregressive sequence log-likelihood`,domain:`generative-models`,level:`common`,tex:`\\log p_\\theta(x_{1:T})=\\sum_{t=1}^{T}\\log p_\\theta(x_t\\mid x_{<t})`,accessibleText:`Log probability of the sequence x one through T equals the sum from t equals one through T of the log probability of token x t given all earlier tokens.`,purpose:`Decomposes sequence likelihood into next-token prediction terms that an autoregressive model can train and evaluate directly.`,provenance:`paper-displayed`,provenanceNote:`This is the probability chain rule in the left-to-right factorization used by causal Transformer language models.`,symbols:[{notationId:`autoregressive-factorization`,symbol:`p_\\theta(x_{1:T})`,role:`Expresses one joint sequence probability through ordered next-token conditionals.`},{notationId:`logarithm`,symbol:`\\log`,role:`Turns the product of token probabilities into a sum of token log probabilities.`},{notationId:`summation`,symbol:`\\sum_{t=1}^{T}`,role:`Aggregates one conditional log-probability contribution per sequence position.`},{notationId:`vertical-bar`,senseId:`conditioning`,symbol:`\\mid`,role:`Reads as given the earlier token prefix.`},{notationId:`tensor-slicing`,symbol:`x_{1:T},x_{<t}`,role:`Selects the complete sequence and each strict prefix.`}],decoder:{define:[`x one through T is a token sequence of length T and theta is the model parameter set.`,`x less than t is the prefix before position t, while p theta assigns the next-token distribution.`],establish:[`Each conditional probability and log probability is scalar; summation reduces the token axis to one sequence score.`],chunk:[`At each token position, condition on the prefix.`,`Read the model probability assigned to the observed next token.`,`Take its logarithm and add contributions across the sequence.`],mainOperator:`The summation is the outer reduction; logarithms convert a joint probability product into additive token evidence.`,describe:`Score a whole sequence by adding how well the model predicted every observed token from its earlier context.`,execute:{setup:`Suppose a two-token sequence receives conditional probabilities 0.5 and 0.25.`,steps:[`Take logs: log 0.5 and log 0.25.`,`Add them: log 0.5 + log 0.25 = log 0.125.`],result:`The sequence probability is 0.125 and its log-likelihood is approximately −2.079 nats.`},relate:`This is the training and evaluation factorization behind next-token prediction; causal masking prevents a term from accessing future tokens.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`neural-language-model-paper`]}},{id:`vae-elbo`,slug:`variational-autoencoder-elbo`,title:`Variational autoencoder ELBO`,domain:`generative-models`,level:`advanced`,tex:`\\mathcal{L}(\\theta,\\phi;x)=\\mathbb{E}_{q_\\phi(z\\mid x)}[\\log p_\\theta(x\\mid z)]-D_{\\mathrm{KL}}(q_\\phi(z\\mid x)\\Vert p(z))`,accessibleText:`The variational objective for x equals expected log decoder probability of x given z under q phi z given x, minus K L divergence from the approximate posterior to the prior.`,purpose:`Balances explaining each observation through latent samples with keeping the learned latent distribution close to the model prior.`,provenance:`paper-displayed`,provenanceNote:`This is the standard single-observation evidence lower bound from Auto-Encoding Variational Bayes, rearranged into reconstruction-minus-KL form.`,symbols:[{notationId:`evidence-lower-bound`,symbol:`\\mathcal{L}(\\theta,\\phi;x)`,role:`Names the scalar lower bound optimized by the VAE.`},{notationId:`expectation`,symbol:`\\mathbb{E}_{q_\\phi}`,role:`Averages reconstruction log-likelihood over inferred latent samples.`},{notationId:`approximate-posterior`,symbol:`q_\\phi(z\\mid x)`,role:`The encoder distribution used to infer latent z from x.`},{notationId:`reconstruction-term`,symbol:`\\log p_\\theta(x\\mid z)`,role:`Rewards latent samples that let the decoder explain the observation.`},{notationId:`kl-divergence`,symbol:`D_{\\mathrm{KL}}(q_\\phi\\Vert p)`,role:`Penalizes deviation of the inferred distribution from the prior.`},{notationId:`prior-distribution`,symbol:`p(z)`,role:`Defines the latent distribution used for generation before observing x.`}],decoder:{define:[`Theta parameterizes the decoder p theta of x given z and phi parameterizes the encoder q phi of z given x.`,`The prior p z is the model's latent distribution before seeing x.`,`The complete expression is a lower bound on log model evidence p theta of x.`],establish:[`Both the expected reconstruction term and KL divergence reduce to scalars per observation, so subtraction is type-compatible.`],chunk:[`Data fit: average log decoder probability under inferred latent samples.`,`Regularization: measure divergence between approximate posterior and prior.`,`Subtract the divergence from data fit to form the lower bound.`],mainOperator:`Subtraction expresses the tradeoff between reconstruction quality and a usable, prior-aligned latent space.`,describe:`Encode x into plausible latent explanations, reward explanations that reconstruct x, and charge for moving too far from the prior.`,execute:{setup:`Suppose expected reconstruction log-likelihood is −3.0 and KL divergence is 0.5.`,steps:[`Keep the reconstruction contribution −3.0.`,`Subtract the KL penalty: −3.0−0.5.`],result:`The ELBO is −3.5; the corresponding negative-ELBO loss is 3.5.`},relate:`The paper uses reparameterized Monte Carlo samples to differentiate the expectation efficiently despite latent randomness.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`vae-paper`]}},{id:`diffusion-forward-process`,slug:`diffusion-closed-form-forward-process`,title:`Diffusion forward-process marginal`,domain:`generative-models`,level:`advanced`,tex:`q(x_t\\mid x_0)=\\mathcal{N}\\!\\left(x_t;\\sqrt{\\bar\\alpha_t}x_0,(1-\\bar\\alpha_t)I\\right)`,accessibleText:`q of x t given x zero is a normal distribution with mean square root alpha bar t times x zero and covariance one minus alpha bar t times the identity.`,purpose:`Samples a noised version at any diffusion time directly from the clean sample without simulating every intermediate step.`,provenance:`paper-displayed`,provenanceNote:`This is the closed-form forward marginal in Denoising Diffusion Probabilistic Models.`,symbols:[{notationId:`diffusion-forward-kernel`,symbol:`q(x_t\\mid x_0)`,role:`Names the fixed distribution of a noised sample conditioned on the clean input.`},{notationId:`normal-distribution`,symbol:`\\mathcal{N}`,role:`Specifies a Gaussian distribution over the sample-shaped tensor x t.`},{notationId:`cumulative-noise-product`,symbol:`\\bar\\alpha_t`,role:`Summarizes signal retained through all forward steps up to t.`},{notationId:`square-root`,symbol:`\\sqrt{\\bar\\alpha_t}`,role:`Scales the clean signal to the correct marginal standard-deviation convention.`},{notationId:`identity-matrix`,symbol:`I`,role:`Indicates isotropic independent Gaussian noise across coordinates.`},{notationId:`vertical-bar`,senseId:`conditioning`,symbol:`\\mid`,role:`Conditions the noised sample on the clean starting sample.`}],decoder:{define:[`x zero is a clean data sample and x t is its noised version at diffusion step t.`,`Alpha bar t is the cumulative product of per-step signal-retention coefficients.`,`The normal distribution's first argument is its mean and second is covariance.`],establish:[`x zero, x t, and the Gaussian mean share the same sample shape; identity covariance spans the flattened sample coordinates.`],chunk:[`Mean: retain square root alpha bar t of the clean sample.`,`Covariance: allocate one minus alpha bar t of isotropic noise variance.`,`Distribution: sample x t from that Gaussian.`],mainOperator:`The normal-distribution constructor is the main verb: it defines the complete conditional law of x t.`,describe:`At time t, keep a scheduled fraction of the clean signal and fill the remaining variance with Gaussian noise.`,execute:{setup:`For scalar x zero=2 and alpha bar t=0.25, use a zero-noise draw for the tiny deterministic illustration.`,steps:[`Signal scale is square root 0.25=0.5.`,`The Gaussian mean is 0.5×2=1.`,`Noise variance is 1−0.25=0.75.`],result:`x t is distributed as Normal(mean 1, variance 0.75).`},relate:`This closed form lets training choose random time steps directly; the learned reverse process is trained to undo the scheduled corruption.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`ddpm-paper`]}},{id:`multi-head-attention-shapes`,slug:`multi-head-attention-tensor-shapes`,title:`Multi-head attention shape flow`,domain:`transformers`,level:`common`,tex:`Q,K,V\\in\\mathbb{R}^{B\\times H\\times T\\times d_h},\\quad A=\\operatorname{softmax}\\!\\left(\\frac{QK^\\top}{\\sqrt{d_h}}\\right)\\in\\mathbb{R}^{B\\times H\\times T\\times T},\\quad AV\\in\\mathbb{R}^{B\\times H\\times T\\times d_h}`,accessibleText:`Q K and V have batch, head, token, and head-width axes; attention weights have batch, head, query-token, and key-token axes; multiplying by V restores a final head-width axis.`,purpose:`Makes the attention equation type-checkable by exposing every tensor axis and the contracted dimensions.`,provenance:`fanout-derived`,provenanceNote:`The shapes are derived from the multi-head and scaled dot-product attention definitions in the Transformer paper, using equal query and key lengths for clarity.`,symbols:[{notationId:`tensor-shape-membership`,symbol:`\\in\\mathbb{R}^{B\\times H\\times T\\times d_h}`,role:`Declares ordered batch, head, token, and per-head feature axes.`},{notationId:`matrix-product`,symbol:`QK^\\top, AV`,role:`Contracts head width to form token-pair scores, then contracts key tokens to mix values.`},{notationId:`transpose`,symbol:`K^\\top`,role:`Swaps key token and feature axes within each batch and head.`},{notationId:`softmax`,symbol:`\\operatorname{softmax}`,role:`Normalizes the key-token axis for every query token.`},{notationId:`axis-index`,symbol:`B,H,T,d_h`,role:`Gives each tensor dimension a semantic role rather than treating shape as a flat size.`}],decoder:{define:[`B is batch size, H is attention-head count, T is sequence length, and d h is width per head.`,`Q, K, and V carry one vector for each batch, head, and token.`,`A contains one normalized key weight for each query token.`],establish:[`Q times K transpose contracts d h, producing T by T per batch and head; A times V contracts the key-token T and returns d h.`],chunk:[`Inputs: B by H by T by d h query, key, and value tensors.`,`Scores: contract feature width to obtain all query-key token pairs.`,`Output: contract normalized key weights with values to restore feature width.`],mainOperator:`Tensor contraction is the structural verb; each matrix product removes one named shared axis and preserves the others.`,describe:`Within every batch and head, compare every query token with every key token, then use those weights to combine value features.`,execute:{setup:`Use B=2, H=4, T=8, and d h=16.`,steps:[`Q, K, and V each have shape 2×4×8×16.`,`QK transpose has shape 2×4×8×8.`,`Multiplying attention weights by V returns 2×4×8×16.`],result:`The attention block preserves one d h vector per token and head.`},relate:`Real implementations may use different query and key lengths, grouped KV heads, packed sequences, or fused layouts while preserving the same contraction logic.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`attention-paper`]}},{id:`layernorm-rmsnorm`,slug:`layernorm-versus-rmsnorm`,title:`LayerNorm and RMSNorm`,domain:`transformers`,level:`common`,tex:`\\operatorname{LN}(x)=\\gamma\\odot\\frac{x-\\mu}{\\sqrt{\\sigma^2+\\epsilon}}+\\beta,\\qquad \\operatorname{RMSNorm}(x)=\\gamma\\odot\\frac{x}{\\sqrt{d^{-1}\\sum_i x_i^2+\\epsilon}}`,accessibleText:`LayerNorm centers x by its mean and scales by standard deviation before gain and bias, while RMSNorm skips centering and scales x by its root mean square before gain.`,purpose:`Shows exactly which centering and bias operations RMSNorm removes from LayerNorm while retaining feature-wise rescaling.`,provenance:`paper-displayed`,provenanceNote:`The paired equations follow the original LayerNorm and RMSNorm definitions with epsilon included for numerical stability.`,symbols:[{notationId:`layer-normalization`,symbol:`\\operatorname{LN}(x)`,role:`Centers and variance-normalizes the selected feature group before learned gain and bias.`},{notationId:`rms-normalization`,symbol:`\\operatorname{RMSNorm}(x)`,role:`Uses the uncentered root mean square and a learned gain.`},{notationId:`hadamard-product`,symbol:`\\gamma\\odot`,role:`Applies one learned gain per normalized feature coordinate.`},{notationId:`sample-mean`,symbol:`\\mu`,role:`Represents the mean across the normalized feature group in the LayerNorm branch.`},{notationId:`square-root`,symbol:`\\sqrt{\\cdot}`,role:`Converts variance or mean-square into a scale with x's units.`},{notationId:`epsilon`,symbol:`\\epsilon`,role:`Stabilizes division when feature spread or RMS is near zero.`}],decoder:{define:[`Mu and sigma squared are the mean and variance over LayerNorm's selected feature group.`,`d is the count of normalized features, gamma is learned gain, and beta is LayerNorm's learned bias.`,`RMSNorm uses mean square without subtracting the feature mean.`],establish:[`Every statistic reduces the feature axis to a broadcastable scalar; both formulas preserve x's complete tensor shape.`],chunk:[`LayerNorm: center x, divide by standard deviation, then apply gain and bias.`,`RMSNorm: divide uncentered x by root mean square, then apply gain.`,`Both share epsilon stabilization and feature-wise scaling.`],mainOperator:`Normalization by a feature-group scale is common to both; mean subtraction is the decisive structural difference.`,describe:`LayerNorm removes feature offset and scale, while RMSNorm removes only scale and performs fewer statistics.`,execute:{setup:`Let x=[1,3], gamma=[1,1], beta=[0,0], and ignore epsilon.`,steps:[`LayerNorm mean is 2 and standard deviation is 1, giving [−1,1].`,`RMS is square root((1²+3²)/2)=square root 5.`,`RMSNorm gives approximately [0.447,1.342].`],result:`The outputs differ because RMSNorm does not center the vector.`},relate:`The RMSNorm paper argues that re-scaling invariance can be retained without LayerNorm's re-centering operation.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`layernorm-paper`,`rmsnorm-paper`]}},{id:`serving-latency-decomposition`,slug:`llm-serving-latency-decomposition`,title:`LLM serving latency decomposition`,domain:`gpu-inference`,level:`common`,tex:`T_{request}\\approx T_{queue}+T_{prefill}+(N_{out}-1)\\operatorname{TPOT}`,accessibleText:`Request latency is approximately queueing time plus prefill time plus output token count minus one times time per output token.`,purpose:`Separates a request's waiting, prompt-processing, and iterative decode contributions so bottlenecks are not hidden in one average.`,provenance:`fanout-derived`,provenanceNote:`This operational decomposition combines standard TTFT and TPOT serving metrics with the prefill/decode phases described in LLM-serving work. It is an approximation, not a displayed PagedAttention equation.`,symbols:[{notationId:`serving-latency`,symbol:`T_{request}`,role:`The end-to-end duration from arrival through final generated token.`},{notationId:`prefill-phase`,symbol:`T_{prefill}`,role:`The prompt-processing duration that initializes hidden states and KV cache.`},{notationId:`time-per-output-token`,symbol:`\\operatorname{TPOT}`,role:`The average incremental duration of decode tokens after the first.`},{notationId:`subscript`,symbol:`request, queue, prefill, out`,role:`Uses descriptive labels rather than array indices to distinguish latency terms.`},{notationId:`approximately-equal`,symbol:`\\approx`,role:`Marks the simplification that later output tokens share one average decode duration.`}],decoder:{define:[`T queue is scheduler waiting time and T prefill is prompt-processing time.`,`N out is generated-token count, while TPOT averages decode time for tokens after the first.`,`The first token is already accounted for by queue and prefill in this simplified decomposition.`],establish:[`Every time term has duration units; the dimensionless token count multiplies time per token to produce duration.`],chunk:[`Before execution: wait in the serving queue.`,`First-token path: process the complete prompt during prefill.`,`Remaining output: multiply later token count by average time per token.`],mainOperator:`Addition composes sequential critical-path phases, while multiplication expands the repeated decode-token phase.`,describe:`Total response time is waiting plus prompt work plus the cadence cost of every generated token after the first.`,execute:{setup:`Let queue time be 20 ms, prefill be 80 ms, output length be 11 tokens, and TPOT be 30 ms.`,steps:[`Later decode tokens: 11−1=10.`,`Decode duration: 10×30 ms=300 ms.`,`Add queue and prefill: 20+80+300 ms.`],result:`Approximate request completion latency is 400 ms, with TTFT near 100 ms.`},relate:`Continuous batching, preemption, variable TPOT, speculative decoding, and overlap can make real request traces depart from this simple additive model.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`pagedattention-paper`]}},{id:`dpo-loss`,slug:`direct-preference-optimization-loss`,title:`Direct preference optimization loss`,domain:`reinforcement-learning`,level:`advanced`,tex:`\\mathcal{L}_{DPO}(\\pi_\\theta;\\pi_{ref})=-\\mathbb{E}_{(x,y_w,y_l)\\sim\\mathcal{D}}\\!\\left[\\log\\sigma\\!\\left(\\beta\\log\\frac{\\pi_\\theta(y_w\\mid x)}{\\pi_{ref}(y_w\\mid x)}-\\beta\\log\\frac{\\pi_\\theta(y_l\\mid x)}{\\pi_{ref}(y_l\\mid x)}\\right)\\right]`,accessibleText:`D P O loss is the negative expected log sigmoid of beta times the winner policy-to-reference log ratio minus beta times the loser policy-to-reference log ratio.`,purpose:`Raises the reference-relative likelihood of preferred responses over dispreferred responses without fitting a separate reward model during policy optimization.`,provenance:`paper-displayed`,provenanceNote:`This is the DPO preference objective from Rafailov et al., with winner and loser notation normalized to Fanout conventions.`,symbols:[{notationId:`dpo-loss`,symbol:`\\mathcal{L}_{DPO}`,role:`Names the scalar preference objective minimized over annotated response pairs.`},{notationId:`expectation`,symbol:`\\mathbb{E}_{(x,y_w,y_l)\\sim\\mathcal{D}}`,role:`Averages the pairwise loss over prompts and preference annotations.`},{notationId:`preference-pair`,symbol:`(y_w,y_l)`,role:`Marks the preferred winner response and dispreferred loser response for one prompt.`},{notationId:`reference-policy`,symbol:`\\pi_{ref}`,role:`Provides the fixed baseline used to measure relative policy movement.`},{notationId:`dpo-logit`,symbol:`\\beta\\log(\\pi_\\theta/\\pi_{ref})`,role:`Turns each response's reference-relative sequence likelihood into an implicit reward score.`},{notationId:`sigmoid`,symbol:`\\sigma`,role:`Converts the winner-minus-loser score difference to a modeled preference probability.`}],decoder:{define:[`x is the prompt, y w is the preferred response, and y l is the dispreferred response.`,`Pi theta is the learned policy, pi ref is a frozen reference policy, and beta controls reference-relative scale.`,`Each log ratio compares one response's complete sequence probability under the learned and reference policies.`],establish:[`Every sequence log probability and log ratio is scalar per response; their difference, sigmoid, logarithm, and expectation preserve a scalar loss.`],chunk:[`Score the preferred response with its learned-to-reference log ratio.`,`Score the dispreferred response the same way and subtract it.`,`Apply sigmoid, take negative log, and average preference pairs.`],mainOperator:`Negative log sigmoid is the pairwise classification loss; the inner difference decides which response the policy favors relative to the reference.`,describe:`Make the preferred answer gain more probability than the rejected answer, measured against the same frozen baseline.`,execute:{setup:`Suppose beta times the winner log ratio is 1.2 and the loser log ratio is 0.2.`,steps:[`Subtract scores: 1.2−0.2=1.0.`,`Sigmoid of 1.0 is about 0.731.`,`Negative log 0.731 is about 0.313.`],result:`This preference pair contributes approximately 0.313 loss; a larger winner margin would reduce it.`},relate:`The reference policy prevents the comparison from depending only on raw sequence likelihood and makes the objective equivalent to an implicit reward-model formulation under the paper's derivation.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`dpo-paper`]}},{id:`vae-reparameterization`,slug:`vae-reparameterization-trick`,title:`VAE reparameterized latent sample`,domain:`generative-models`,level:`advanced`,tex:`\\epsilon\\sim\\mathcal{N}(0,I),\\qquad z=\\mu_\\phi(x)+\\sigma_\\phi(x)\\odot\\epsilon`,accessibleText:`Epsilon is sampled from a standard normal distribution, and latent z equals encoder mean mu phi of x plus encoder standard deviation sigma phi of x elementwise times epsilon.`,purpose:`Expresses a random posterior sample as a differentiable transformation of parameter-free noise so gradients can flow into encoder parameters.`,provenance:`paper-displayed`,provenanceNote:`This is the Gaussian reparameterization used in Auto-Encoding Variational Bayes, written with vector-valued diagonal standard deviation.`,symbols:[{notationId:`reparameterization-trick`,symbol:`z=\\mu_\\phi(x)+\\sigma_\\phi(x)\\odot\\epsilon`,role:`Moves encoder parameters into a deterministic transformation of a base-noise draw.`},{notationId:`standard-normal-noise`,symbol:`\\epsilon\\sim\\mathcal{N}(0,I)`,role:`Supplies random noise whose distribution does not depend on encoder parameters.`},{notationId:`vae-mean`,symbol:`\\mu_\\phi(x)`,role:`Centers the approximate posterior for the current observation.`},{notationId:`hadamard-product`,symbol:`\\odot`,role:`Scales each latent noise coordinate by its predicted standard deviation.`},{notationId:`tilde`,senseId:`distributed-as`,symbol:`\\sim`,role:`Reads as epsilon is distributed according to the standard normal law.`}],decoder:{define:[`Mu phi of x and sigma phi of x are latent-width vectors predicted by the encoder.`,`Epsilon is a standard-normal vector independent of phi, while z is the resulting approximate-posterior sample.`],establish:[`Mean, standard deviation, epsilon, and z have the same latent vector shape; elementwise multiplication preserves it and addition is type-compatible.`],chunk:[`Draw parameter-free standard Gaussian noise.`,`Scale noise coordinatewise by posterior standard deviation.`,`Shift by posterior mean to obtain the latent sample.`],mainOperator:`The affine transformation of epsilon is the sampling mechanism; the distribution statement defines the only random input.`,describe:`Generate a posterior sample by stretching and shifting reusable standard noise instead of sampling from a parameter-dependent node directly.`,execute:{setup:`Use scalar mean 2, standard deviation 0.5, and sampled epsilon −1.`,steps:[`Scale noise: 0.5×(−1)=−0.5.`,`Shift by the mean: 2−0.5.`],result:`The latent sample z is 1.5.`},relate:`Because z is now a differentiable function of mu and sigma, automatic differentiation can estimate the ELBO's pathwise gradient.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`vae-paper`]}},{id:`diffusion-noise-objective`,slug:`ddpm-noise-prediction-objective`,title:`Diffusion noise-prediction objective`,domain:`generative-models`,level:`advanced`,tex:`\\mathcal{L}_{simple}(\\theta)=\\mathbb{E}_{t,x_0,\\epsilon}\\!\\left[\\lVert\\epsilon-\\epsilon_\\theta(x_t,t)\\rVert_2^2\\right]`,accessibleText:`The simple diffusion loss is the expectation over time, clean samples, and Gaussian noise of the squared two norm between the true noise epsilon and predicted noise epsilon theta of noisy x t and time t.`,purpose:`Trains a denoising network to identify the exact Gaussian noise used to corrupt a clean sample at a randomly selected timestep.`,provenance:`paper-displayed`,provenanceNote:`This is the simplified noise-prediction objective from Denoising Diffusion Probabilistic Models.`,symbols:[{notationId:`noise-prediction-loss`,symbol:`\\mathcal{L}_{simple}`,role:`Names the DDPM simplified training objective.`},{notationId:`expectation`,symbol:`\\mathbb{E}_{t,x_0,\\epsilon}`,role:`Averages random timesteps, data examples, and noise draws.`},{notationId:`epsilon-prediction`,symbol:`\\epsilon_\\theta(x_t,t)`,role:`Returns the model's sample-shaped estimate of the injected Gaussian noise.`},{notationId:`norm`,symbol:`\\lVert\\cdot\\rVert_2^2`,role:`Squares and sums coordinate-wise residuals into one scalar per sample.`},{notationId:`diffusion-timestep`,symbol:`t`,role:`Selects the schedule noise level supplied to the model.`}],decoder:{define:[`x zero is clean data and x t is its scheduled noisy version at sampled time t.`,`Epsilon is the actual standard-normal noise used to form x t, while epsilon theta is the network prediction.`],establish:[`True and predicted noise share the complete sample tensor shape; the squared norm reduces coordinates and expectation reduces samples and timesteps.`],chunk:[`Corrupt x zero at a sampled timestep using epsilon.`,`Predict that epsilon from x t and t.`,`Square the residual norm and average training draws.`],mainOperator:`Expectation is the outer reduction, while the squared norm defines the per-example regression error.`,describe:`Show the model a noisy sample and noise level, then ask it to reconstruct the noise that was added.`,execute:{setup:`Let true noise be [1,−1] and predicted noise [0.5,−0.5].`,steps:[`Residual is [0.5,−0.5].`,`Square coordinates to get [0.25,0.25].`,`Sum them to obtain the squared two norm.`],result:`This draw contributes 0.5 before expectation averaging.`},relate:`The DDPM derivation connects this simple denoising regression to a variational objective for the learned reverse diffusion process.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`ddpm-paper`]}},{id:`rope-rotation`,slug:`rotary-position-relative-dot-product`,title:`RoPE relative-position rotation`,domain:`transformers`,level:`advanced`,tex:`(R_{\\Theta,m}q_m)^\\top(R_{\\Theta,n}k_n)=q_m^\\top R_{\\Theta,n-m}k_n`,accessibleText:`Rotated query at position m transpose times rotated key at position n equals query m transpose times the relative rotary matrix at position difference n minus m times key n.`,purpose:`Shows why rotary position embedding makes a query-key attention score depend on relative position even though each vector receives an absolute-position rotation.`,provenance:`paper-displayed`,provenanceNote:`This is the core RoFormer inner-product identity, with projection notation omitted to isolate the positional mechanism.`,symbols:[{notationId:`rope-rotation-matrix`,symbol:`R_{\\Theta,m},R_{\\Theta,n}`,role:`Applies position-dependent orthogonal rotations to paired query and key coordinates.`},{notationId:`rope-relative-position`,symbol:`R_{\\Theta,n-m}`,role:`Combines the two absolute rotations into one rotation indexed by their position difference.`},{notationId:`transpose`,symbol:`^\\top`,role:`Turns the rotated query into the left operand of a dot product.`},{notationId:`dot-product`,symbol:`q^\\top k`,role:`Contracts the feature axis to produce one scalar attention score.`},{notationId:`orthogonal-matrix`,symbol:`R`,role:`Ensures inverse rotation is obtained by transposition when the two factors combine.`}],decoder:{define:[`q m and k n are head-width query and key vectors at token positions m and n.`,`R theta m rotates paired coordinates by angles proportional to position m and feature-specific frequencies.`],establish:[`Every R is d by d, q and k are length d, and the complete expression contracts to one scalar attention score.`],chunk:[`Rotate query coordinates by absolute position m.`,`Rotate key coordinates by absolute position n.`,`Combine transposed query rotation with key rotation to obtain a relative rotation n minus m.`],mainOperator:`The dot product is the output operation; orthogonal rotation algebra transforms its two absolute phases into one relative phase.`,describe:`Rotate queries and keys separately, yet make their similarity depend on the distance between token positions.`,execute:{setup:`In one feature pair, let query and key both be [1,0], with angles m theta=30 degrees and n theta=90 degrees.`,steps:[`Rotated query is [cos30,sin30].`,`Rotated key is [cos90,sin90].`,`Their dot product is cos(90−30)=cos60.`],result:`The score contribution is 0.5 and depends on the relative angle of 60 degrees.`},relate:`Implementations apply sine and cosine elementwise rather than constructing full block-diagonal matrices, but the same identity governs the result.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`rope-paper`]}},{id:`moe-top-k-routing`,slug:`mixture-of-experts-top-k-routing`,title:`Top-k mixture-of-experts routing`,domain:`transformers`,level:`advanced`,tex:`\\mathcal{T}(x)=\\operatorname{TopK}(p(x),k),\\qquad y=\\sum_{e\\in\\mathcal{T}(x)}\\tilde p_e(x)E_e(x)`,accessibleText:`The selected expert set T of x is top k of router probabilities p of x, and output y is the sum over selected experts of normalized routing weight p tilde e times expert E e of x.`,purpose:`Makes sparse conditional computation explicit by separating expert selection from the weighted combination of only selected expert outputs.`,provenance:`fanout-derived`,provenanceNote:`This generalized top-k notation is derived from the sparse routing mechanism in Switch Transformers, whose simplest displayed form selects one expert; Fanout makes the selected set explicit for k experts.`,symbols:[{notationId:`mixture-of-experts`,symbol:`y=\\sum_e\\tilde p_eE_e(x)`,role:`Combines selected expert transformations into the layer output.`},{notationId:`top-k-selection`,symbol:`\\operatorname{TopK}(p(x),k)`,role:`Returns the indices of the k highest router weights for this token.`},{notationId:`router-probability`,symbol:`p_e(x),\\tilde p_e(x)`,role:`Scores experts and supplies normalized mixture weights after sparse selection.`},{notationId:`summation`,symbol:`\\sum_{e\\in\\mathcal{T}(x)}`,role:`Aggregates only outputs whose expert indices belong to the selected set.`},{notationId:`membership`,symbol:`e\\in\\mathcal{T}(x)`,role:`Restricts the bound expert index to the selected routing set.`}],decoder:{define:[`p of x is one router probability per expert and T of x is the selected index set.`,`E e is expert e's feed-forward transformation, while p tilde denotes weights renormalized over selected experts.`],establish:[`Every selected expert maps x to the same model-width output shape, so scalar-weighted outputs can be added without shape mismatch.`],chunk:[`Compute routing probabilities over all experts.`,`Keep the top k expert indices and optionally renormalize their weights.`,`Evaluate selected experts and sum their weighted outputs.`],mainOperator:`Top-k creates sparse control flow, and the following summation combines only the active branches.`,describe:`Choose a few experts for each token, run only those experts, and blend their answers using router weights.`,execute:{setup:`Let router probabilities be [0.6,0.3,0.1], k=2, and scalar expert outputs [10,4,8].`,steps:[`Select experts one and two.`,`Renormalize selected weights to two thirds and one third.`,`Combine: two thirds times 10 plus one third times 4.`],result:`The sparse mixture output is 8 before any following projection.`},relate:`Expert capacity, token dispatch, all-to-all communication, and load-balancing losses determine whether this mathematical sparsity produces efficient distributed execution.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`switch-transformer-paper`]}},{id:`tensor-parallel-communication`,slug:`row-parallel-linear-all-reduce`,title:`Row-parallel tensor communication`,domain:`gpu-inference`,level:`advanced`,tex:`Y_r=X_rW_r,\\qquad Y=\\operatorname{AllReduce}_{sum}(\\{Y_r\\}_{r=1}^{p})`,accessibleText:`Each rank r computes local output Y r as input shard X r times weight shard W r, then global Y is the sum all-reduce of all rank-local partial outputs from rank one through p.`,purpose:`Shows why sharding a linear layer across its input dimension creates full-shaped partial outputs that require a sum collective.`,provenance:`fanout-derived`,provenanceNote:`This normalized equation is derived from Megatron-LM's row-parallel linear-layer construction and NCCL sum all-reduce semantics.`,symbols:[{notationId:`row-parallel-linear`,symbol:`Y_r=X_rW_r`,role:`Computes one rank's partial contribution to every output feature.`},{notationId:`tensor-parallel-shard`,symbol:`X_r,W_r`,role:`Marks matching input-feature and weight-row shards owned by rank r.`},{notationId:`matrix-product`,symbol:`X_rW_r`,role:`Contracts the local input-feature axis and produces a full output-width partial tensor.`},{notationId:`all-reduce`,symbol:`\\operatorname{AllReduce}_{sum}`,role:`Adds partial outputs and returns the complete result to every participating rank.`},{notationId:`subscript`,symbol:`r`,role:`Indexes device-local tensors rather than examples or timesteps.`}],decoder:{define:[`p is tensor-parallel rank count and r identifies one device's matching input and weight shards.`,`Y r is a full output-width partial result, while Y is the complete linear-layer output available after communication.`],establish:[`Each local matrix product has the same batch-by-output shape; elementwise sum all-reduce preserves that shape and combines the contracted input partitions.`],chunk:[`Partition the input-feature axis and corresponding weight rows.`,`Compute one full-shaped partial output per rank.`,`All-reduce with sum so every rank receives the complete output.`],mainOperator:`Sum all-reduce is the distributed reduction that reconstructs the mathematical result of the unsharded matrix product.`,describe:`Every device computes part of each output activation, then the devices add those parts together.`,execute:{setup:`With two ranks, suppose their scalar partial outputs are Y one=3 and Y two=5.`,steps:[`Rank one contributes 3.`,`Rank two contributes 5.`,`The sum all-reduce adds 3+5 and distributes the result.`],result:`Every rank receives the complete output Y=8.`},relate:`Column-parallel layers instead produce distinct output shards; Megatron pairs row and column partitions to avoid unnecessary collectives between adjacent operations.`},review:{status:`reviewed`,reviewedAt:r,sourceIds:[`megatron-paper`,`nccl-collectives`]}}]}));export{n,a as r,i as t};